import torch
import torch.nn as nn
class Model(nn.Module):
    def forward(self,x):
        return torch.sum(x,dim=0)

import torch
import torch.nn as nn
class Model(nn.Module):
    def forward(self,x):
        return x.sum(dim=-1,keepdim=True)

import torch
import torch.nn as nn
class Model(nn.Module):
    def __init__(self,axis:int=1):
        super().__init__()
        self.axis=axis
    def forward(self,x):
        return torch.sum(x,dim=self.axis)
